const VERCEL_SERVICE_NAME_PATTERN=/^[a-z](?:[a-z_-]*[a-z])?$/,MAX_VERCEL_SERVICE_NAME_LENGTH=64;function isValidVercelServiceName(e){return e.length<=64&&VERCEL_SERVICE_NAME_PATTERN.test(e)}function assertValidVercelServiceName(e,t){if(!isValidVercelServiceName(e))throw Error(`${t} ${JSON.stringify(e)} is invalid. Vercel service names must use 1-64 lowercase letters, hyphens, or underscores, beginning and ending with a letter.`)}export{MAX_VERCEL_SERVICE_NAME_LENGTH,assertValidVercelServiceName,isValidVercelServiceName};